117	// ─── No registry match ────────────────────────────────────────────────────
118	
119	describe('ledger_get_repository_context — no registry match', () => {
120	  it('returns null for repository_id, repository_label, and strategic_vision when no registry file exists', async () => {
121	    await seedProject('my-repo', '2026-01-01-project-alpha');
122	
123	    const result = await getRepositoryContext({
