128	    const data = parseResult(result as any);
129	    expect(data.repository_id).toBeNull();
130	    expect(data.repository_label).toBeNull();
131	    expect(data.strategic_vision).toBeNull();
132	  });
133	
134	  it('reads projects from the single derived folder name when no registry match', async () => {
135	    await seedProject('my-repo', '2026-01-01-project-alpha');
136	    await seedProject('my-repo', '2026-01-02-project-beta');
137	
138	    const result = await getRepositoryContext({
139	      repository_name: 'my-repo',
