141	    });
142	
143	    const data = parseResult(result as any);
144	    expect(data.total_projects).toBe(2);
145	    expect(data.projects).toHaveLength(2);
146	  });
147	
148	  it('returns empty projects array for an empty repo folder (no registry)', async () => {
149	    const result = await getRepositoryContext({
150	      repository_name: 'my-repo',
151	      include_insights: false,
152	    });
153	
154	    const data = parseResult(result as any);
155	    expect(data.total_projects).toBe(0);
156	    expect(data.projects).toEqual([]);
157	  });
158	});
159	
160	// ─── Registry match ───────────────────────────────────────────────────────
161	
162	describe('ledger_get_repository_context — registry match', () => {
163	  it('returns repository_id, repository_label, and strategic_vision from the registry entry', async () => {
164	    await seedRegistry({
165	      repositories: [
166	        {
167	          id: 'my-repo',
168	          label: 'My Repository',
169	          folder_names: ['my-repo'],
170	          vision: {
171	            short_term: 'Ship MVP',
172	            mid_term: 'Expand feature set',
173	            long_term: null,
174	          },
175	          created_at: '2026-01-01T00:00:00Z',
176	          last_modified: '2026-01-01T00:00:00Z',
177	        },
178	      ],
179	    });
180	
181	    const result = await getRepositoryContext({
182	      repository_name: 'my-repo',
