184	    });
185	
186	    const data = parseResult(result as any);
187	    expect(data.repository_id).toBe('my-repo');
188	    expect(data.repository_label).toBe('My Repository');
189	    expect(data.strategic_vision.short_term).toBe('Ship MVP');
190	    expect(data.strategic_vision.mid_term).toBe('Expand feature set');
191	    expect(data.strategic_vision.long_term).toBeNull();
192	  });
193	
194	  it('aggregates projects from ALL folder_names declared in the registry', async () => {
195	    await seedRegistry({
196	      repositories: [
197	        {
198	          id: 'multi-folder-repo',
199	          label: 'Multi Folder Repo',
200	          folder_names: ['folder-a', 'folder-b'],
201	          vision: { short_term: null, mid_term: null, long_term: null },
202	          created_at: '2026-01-01T00:00:00Z',
