223	// ─── Sorting ──────────────────────────────────────────────────────────────
224	
225	describe('ledger_get_repository_context — sorting', () => {
226	  it('sorts projects by date_created descending (most recent first)', async () => {
227	    await seedProject('my-repo', '2026-01-01-oldest', { date_created: '2026-01-01T00:00:00Z' });
